import os, re, json

# Load all grids from this session
d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
G = {}

for match in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = match[1], int(match[2]), int(match[3])
    rows = [r.split() for r in t[match.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

print("Available grids:", sorted(G.keys()))
for k, v in G.items():
    print(f"{k}: {len(v)}x{len(v[0])}")

